// Parser CSV mínimo (soporta comillas). Devuelve array de objetos usando la fila 1 como cabeceras.
const parseCsv = (texto) => {
  const filas = []; let fila = [], celda = '', dentro = false;
  const s = String(texto ?? '');
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (dentro) {
      if (c === '"' && s[i + 1] === '"') { celda += '"'; i++; }
      else if (c === '"') dentro = false;
      else celda += c;
    } else if (c === '"') dentro = true;
    else if (c === ',') { fila.push(celda); celda = ''; }
    else if (c === '\n') { fila.push(celda); filas.push(fila); fila = []; celda = ''; }
    else if (c !== '\r') celda += c;
  }
  if (celda !== '' || fila.length) { fila.push(celda); filas.push(fila); }
  const [cab, ...datos] = filas.filter((f) => f.some((x) => x !== ''));
  return (datos ?? []).map((f) => Object.fromEntries(cab.map((h, i) => [h.trim().toLowerCase(), (f[i] ?? '').trim()])));
};
const num = (v) => { const n = parseFloat(String(v).replace(',', '.')); return isFinite(n) ? n : 0; };

export const code = async (inputs) => {
  const posiciones = parseCsv(inputs.posicionesCsv).filter((p) => String(p.call_abierto).toLowerCase() === 'si');
  if (!posiciones.length) return { hayAvisos: false, resumen: 'Sin calls abiertos.' };

  const hoy = new Date().toISOString().slice(0, 10);
  const avisos = [];
  for (const p of posiciones) {
    const ticker = String(p.ticker).toUpperCase();
    const venc = String(p.vencimiento);
    try {
      const r = await fetch('https://finnhub.io/api/v1/calendar/earnings?from=' + hoy + '&to=' + venc +
        '&symbol=' + ticker + '&token=' + inputs.finnhubToken);
      const datos = await r.json();
      for (const e of datos?.earningsCalendar ?? []) {
        // Regla: sin earnings antes del vencimiento del ciclo
        if (e.date >= hoy && e.date <= venc)
          avisos.push(ticker + ': earnings el ' + e.date + ' ANTES del vencimiento ' + venc +
            '. Valora recomprar el call antes del evento.');
      }
    } catch (err) {
      avisos.push(ticker + ': error consultando earnings (' + err.message + ').');
    }
  }
  return { hayAvisos: avisos.length > 0, resumen: avisos.join('\n') || 'Sin earnings en los ciclos abiertos.' };
};
